&lt;h2&gt;


  backend/&lt;strong&gt;init&lt;/strong&gt;.py
&lt;/h2&gt;

&lt;p&gt;&lt;code&gt;&lt;/code&gt;`python&lt;br&gt;
from flask import Flask, request, jsonify&lt;br&gt;
from flask_cors import CORS&lt;br&gt;
import sqlite3&lt;br&gt;
import bcrypt&lt;br&gt;
from datetime import datetime&lt;/p&gt;

&lt;p&gt;VAT = 0.20&lt;/p&gt;

&lt;p&gt;def create_app():&lt;br&gt;
    app = Flask(&lt;strong&gt;name&lt;/strong&gt;)&lt;br&gt;
    CORS(app)&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;def db():
    conn = sqlite3.connect("shop.db")
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = db()

    conn.executescript("""
    CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT,
        email TEXT UNIQUE,
        password TEXT,
        first_name TEXT,
        last_name TEXT,
        role TEXT DEFAULT 'user',
        account_created TEXT,
        last_login TEXT
    );

    CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT,
        description TEXT,
        price REAL,
        stock INTEGER
    );

    CREATE TABLE IF NOT EXISTS orders (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER,
        username TEXT,
        total REAL,
        created_at TEXT
    );

    CREATE TABLE IF NOT EXISTS order_items (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        order_id INTEGER,
        product_name TEXT,
        product_desc TEXT,
        qty INTEGER,
        price REAL,
        vat_price REAL
    );
    """)

    conn.commit()
    conn.close()

init_db()

@app.route("/")
def home():
    return jsonify({"status": "API running"})

# ───────── AUTH ─────────
@app.route("/register", methods=["POST"])
def register():
    d = request.json
    hashed = bcrypt.hashpw(d["password"].encode(), bcrypt.gensalt())

    conn = db()
    conn.execute("""
        INSERT INTO users(username, email, password, account_created)
        VALUES (?, ?, ?, ?)
    """, (d["username"], d["email"], hashed.decode(), datetime.now().isoformat()))
    conn.commit()
    conn.close()

    return jsonify({"msg": "registered"})

@app.route("/login", methods=["POST"])
def login():
    d = request.json
    conn = db()

    user = conn.execute(
        "SELECT * FROM users WHERE email=?",
        (d["email"],)
    ).fetchone()

    if not user:
        return jsonify({"error": "not found"}), 404

    if not bcrypt.checkpw(d["password"].encode(), user["password"].encode()):
        return jsonify({"error": "wrong password"}), 401

    conn.execute(
        "UPDATE users SET last_login=? WHERE id=?",
        (datetime.now().isoformat(), user["id"])
    )

    conn.commit()
    conn.close()

    return jsonify({
        "user_id": user["id"],
        "username": user["username"],
        "role": user["role"]
    })

# ───────── PRODUCTS ─────────
@app.route("/products")
def products():
    conn = db()
    rows = conn.execute("SELECT * FROM products").fetchall()
    conn.close()
    return jsonify([dict(r) for r in rows])

# ───────── VAT FUNCTION ─────────
def vat(price):
    return round(price * (1 + VAT), 2)

# ───────── CHECKOUT ─────────
@app.route("/checkout", methods=["POST"])
def checkout():
    d = request.json
    conn = db()

    user = conn.execute(
        "SELECT username FROM users WHERE id=?",
        (d["user_id"],)
    ).fetchone()

    total = 0

    for item in d["cart"]:
        p = conn.execute(
            "SELECT * FROM products WHERE id=?",
            (item["id"],)
        ).fetchone()

        total += p["price"] * item["qty"]

    cur = conn.cursor()

    cur.execute("""
        INSERT INTO orders(user_id, username, total, created_at)
        VALUES (?, ?, ?, ?)
    """, (d["user_id"], user["username"], total, datetime.now().isoformat()))

    order_id = cur.lastrowid

    for item in d["cart"]:
        p = conn.execute(
            "SELECT * FROM products WHERE id=?",
            (item["id"],)
        ).fetchone()

        conn.execute("""
            INSERT INTO order_items(
                order_id, product_name,
                product_desc, qty,
                price, vat_price
            )
            VALUES (?, ?, ?, ?, ?, ?)
        """, (
            order_id,
            p["name"],
            p["description"],
            item["qty"],
            p["price"],
            vat(p["price"])
        ))

    conn.commit()
    conn.close()

    return jsonify({"msg": "order created"})

# ───────── USER ACCOUNT ─────────
@app.route("/me")
def me():
    user_id = request.args.get("user_id")

    conn = db()
    user = conn.execute(
        "SELECT * FROM users WHERE id=?",
        (user_id,)
    ).fetchone()

    conn.close()
    return jsonify(dict(user))

@app.route("/me", methods=["PUT"])
def update_me():
    d = request.json

    conn = db()
    conn.execute("""
        UPDATE users
        SET username=?, first_name=?, last_name=?
        WHERE id=?
    """, (d["username"], d["first_name"], d["last_name"], d["user_id"]))

    conn.commit()
    conn.close()

    return jsonify({"msg": "updated"})

# ───────── ORDERS ─────────
@app.route("/me/orders")
def my_orders():
    user_id = request.args.get("user_id")

    conn = db()

    orders = conn.execute(
        "SELECT * FROM orders WHERE user_id=?",
        (user_id,)
    ).fetchall()

    result = []

    for o in orders:
        items = conn.execute(
            "SELECT * FROM order_items WHERE order_id=?",
            (o["id"],)
        ).fetchall()

        result.append({
            "order": dict(o),
            "items": [dict(i) for i in items]
        })

    conn.close()
    return jsonify(result)

return app
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;

&lt;p&gt;app = create_app()&lt;/p&gt;

