import Orders from "./pages/Orders";&lt;br&gt;
import Admin from "./pages/Admin";&lt;/p&gt;

&lt;p&gt;export default function App() {&lt;br&gt;
  const user = JSON.parse(localStorage.getItem("user") || "{}");&lt;/p&gt;

&lt;p&gt;return (&lt;br&gt;
    &lt;br&gt;
      &lt;br&gt;
        Home |&lt;br&gt;
        Shop |&lt;br&gt;
        Cart |&lt;br&gt;
        Account |&lt;br&gt;
        Orders |&lt;br&gt;
        {user.role === "admin" &amp;amp;&amp;amp; Admin}&lt;br&gt;
      &lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;  &amp;lt;Routes&amp;gt;
    &amp;lt;Route path="/" element={&amp;lt;Home /&amp;gt;} /&amp;gt;
    &amp;lt;Route path="/shop" element={&amp;lt;Shop /&amp;gt;} /&amp;gt;
    &amp;lt;Route path="/cart" element={&amp;lt;Cart /&amp;gt;} /&amp;gt;
    &amp;lt;Route path="/account" element={&amp;lt;Account /&amp;gt;} /&amp;gt;
    &amp;lt;Route path="/orders" element={&amp;lt;Orders /&amp;gt;} /&amp;gt;
    &amp;lt;Route path="/admin" element={&amp;lt;Admin /&amp;gt;} /&amp;gt;
  &amp;lt;/Routes&amp;gt;
&amp;lt;/BrowserRouter&amp;gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;

&lt;p&gt;);&lt;br&gt;
}&lt;br&gt;
`&lt;code&gt;&lt;/code&gt;&lt;/p&gt;




&lt;h1&gt;


  📄 Pages
&lt;/h1&gt;

&lt;h2&gt;


  Home.jsx
&lt;/h2&gt;

&lt;p&gt;&lt;code&gt;&lt;/code&gt;&lt;code&gt;jsx&lt;br&gt;
export default function Home() {&lt;br&gt;
  return &amp;lt;h1&amp;gt;Welcome to the Store 🛒&amp;lt;/h1&amp;gt;;&lt;br&gt;
}&lt;br&gt;
&lt;/code&gt;&lt;code&gt;&lt;/code&gt;&lt;/p&gt;




&lt;h2&gt;


  Shop.jsx
&lt;/h2&gt;

&lt;p&gt;&lt;code&gt;&lt;/code&gt;`jsx&lt;br&gt;
import { useEffect, useState } from "react";&lt;br&gt;
import { API } from "../api";&lt;/p&gt;

&lt;p&gt;export default function Shop() {&lt;br&gt;
  const [products, setProducts] = useState([]);&lt;/p&gt;

&lt;p&gt;useEffect(() =&amp;gt; {&lt;br&gt;
    fetch(API + "/products")&lt;br&gt;
      .then(r =&amp;gt; r.json())&lt;br&gt;
      .then(setProducts);&lt;br&gt;
  }, []);&lt;/p&gt;

&lt;p&gt;const add = (p) =&amp;gt; {&lt;br&gt;
    const cart = JSON.parse(localStorage.getItem("cart") || "[]");&lt;br&gt;
    const found = cart.find(i =&amp;gt; i.id === p.id);&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;if (found) found.qty++;
else cart.push({ ...p, qty: 1 });

localStorage.setItem("cart", JSON.stringify(cart));
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;

&lt;p&gt;};&lt;/p&gt;

&lt;p&gt;return (&lt;br&gt;
    &lt;/p&gt;
&lt;br&gt;
      {products.map(p =&amp;gt; (&lt;br&gt;
        &lt;br&gt;
          &lt;h3&gt;{p.name}&lt;/h3&gt;
&lt;br&gt;
           add(p)}&amp;gt;Add to Cart&lt;br&gt;
        &lt;br&gt;
      ))}&lt;br&gt;
    &lt;br&gt;
  );&lt;br&gt;
}&lt;br&gt;
`&lt;code&gt;&lt;/code&gt;


&lt;h2&gt;


  Cart.jsx
&lt;/h2&gt;

&lt;p&gt;&lt;code&gt;&lt;/code&gt;`jsx&lt;br&gt;
import { API } from "../api";&lt;/p&gt;

&lt;p&gt;export default function Cart() {&lt;br&gt;
  const cart = JSON.parse(localStorage.getItem("cart") || "[]");&lt;br&gt;
  const user = JSON.parse(localStorage.getItem("user") || "{}");&lt;/p&gt;

&lt;p&gt;const checkout = async () =&amp;gt; {&lt;br&gt;
    await fetch(API + "/checkout", {&lt;br&gt;
      method: "POST",&lt;br&gt;
      headers: { "Content-Type": "application/json" },&lt;br&gt;
      body: JSON.stringify({ user_id: user.user_id, cart })&lt;br&gt;
    });&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;localStorage.removeItem("cart");
alert("Order placed");
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;

&lt;p&gt;};&lt;/p&gt;

&lt;p&gt;return (&lt;br&gt;
    &lt;/p&gt;
&lt;br&gt;
      {cart.map(i =&amp;gt; (&lt;br&gt;
        &lt;p&gt;{i.name} x{i.qty}&lt;/p&gt;
&lt;br&gt;
      ))}&lt;br&gt;
      Checkout&lt;br&gt;
    &lt;br&gt;
  );&lt;br&gt;
}&lt;br&gt;
`&lt;code&gt;&lt;/code&gt;


&lt;h2&gt;


  Account.jsx (EDIT USER)
&lt;/h2&gt;

&lt;p&gt;&lt;code&gt;&lt;/code&gt;`jsx&lt;br&gt;
import { useEffect, useState } from "react";&lt;br&gt;
import { API } from "../api";&lt;/p&gt;

&lt;p&gt;export default function Account() {&lt;br&gt;
  const user = JSON.parse(localStorage.getItem("user") || "{}");&lt;br&gt;
