&lt;p&gt;useEffect(() =&amp;gt; {&lt;br&gt;
    fetch(API + "/me?user_id=" + user.user_id)&lt;br&gt;
      .then(r =&amp;gt; r.json())&lt;br&gt;
      .then(setForm);&lt;br&gt;
  }, []);&lt;/p&gt;

&lt;p&gt;const save = async () =&amp;gt; {&lt;br&gt;
    await fetch(API + "/me", {&lt;br&gt;
      method: "PUT",&lt;br&gt;
      headers: { "Content-Type": "application/json" },&lt;br&gt;
      body: JSON.stringify({ ...form, user_id: user.user_id })&lt;br&gt;
    });&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;alert("Saved");
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;

&lt;p&gt;};&lt;/p&gt;

&lt;p&gt;return (&lt;br&gt;
    &lt;/p&gt;
&lt;br&gt;
       setForm({ ...form, username: e.target.value })} /&amp;gt;&lt;br&gt;
       setForm({ ...form, first_name: e.target.value })} /&amp;gt;&lt;br&gt;
       setForm({ ...form, last_name: e.target.value })} /&amp;gt;&lt;br&gt;
      Save&lt;br&gt;
    &lt;br&gt;
  );&lt;br&gt;
}&lt;br&gt;
`&lt;code&gt;&lt;/code&gt;


&lt;h2&gt;


  Orders.jsx
&lt;/h2&gt;

&lt;p&gt;&lt;code&gt;&lt;/code&gt;`jsx&lt;br&gt;
import { useEffect, useState } from "react";&lt;br&gt;
import { API } from "../api";&lt;/p&gt;

&lt;p&gt;export default function Orders() {&lt;br&gt;
  const user = JSON.parse(localStorage.getItem("user") || "{}");&lt;br&gt;
